<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{AttendanceRecord,Employee};use Illuminate\Http\Request;class AttendanceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.attendance',['records'=>AttendanceRecord::with('employee')->where('property_id',$p)->latest('attendance_date')->paginate(30),'employees'=>Employee::where('property_id',$p)->where('status','active')->orderBy('first_name')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['employee_id'=>'required|integer','attendance_date'=>'required|date','clock_in'=>'nullable|date','clock_out'=>'nullable|date','status'=>'required|max:30','notes'=>'nullable|max:1000']);$in=$d['clock_in']??null;$out=$d['clock_out']??null;$hours=$in&&$out?max(0,round((strtotime($out)-strtotime($in))/3600,2)):0;$d+=['property_id'=>$p,'hours_worked'=>$hours,'recorded_by'=>auth()->id()];AttendanceRecord::updateOrCreate(['employee_id'=>$d['employee_id'],'attendance_date'=>$d['attendance_date']],$d);return back()->with('success','Attendance saved.');}}